insert into freight_matrices (code, name, carrier, active, basis, per_kg_on, cubic_factor_kg_m3, fuel_levy_percent, margin_percent, consolidate, notes) values ('capital-taxi-mel', 'Capital Group taxi truck ex Thomastown', 'Capital Group', false, 'cost', 'excess', 333, 0, 15, true, 'Capital Group Standard Hourly Hire - VIC, supplied 27/10/26. Ex Thomastown. Priced at MINIMUM HIRE (min hours x hourly rate) - real jobs bill pickup to delivery plus return, so this is a floor. Rates ex GST and ex fuel: SET fuel_levy_percent BEFORE ACTIVATING. Not priced: Hydraulic tailgate 6T $46.80/h, 8T $53.95, 12T $62.40, 14T $68.90; Crane/Hiab 8T $97.50, 12T $104.00, 14T $110.50 (4h minimum). Booked 6am-4pm Mon-Fri; VIP/after-4pm surcharges, 60-120 min specialised pickups, mobile and toll charges not modelled. Capital also quoted 1T courier rates (SC/SSW/SLV/SH/S1, 4-5h standard) - that card is not loaded yet.');
